/* ── Panel navigation ──────────────────────────── */
function goPanel(idx){
  if(idx<0||idx>=PANELS.length)return;
  PANELS.forEach(function(id,i){
    el(id)||qa('[data-panel="'+id+'"]').forEach(function(p){p.classList.toggle('on',i===idx);});
    qa('[data-panel="'+PANELS[i]+'"]').forEach(function(p){p.classList.toggle('on',i===idx);});
    var sn=document.querySelector('.sn[data-to="'+PANELS[i]+'"]');
    if(sn){sn.classList.toggle('on',i===idx);sn.classList.toggle('been',i<idx);}
  });
  cur=idx;
  el('btn_back').classList.toggle('ghost',idx===0);
  el('btn_next').classList.toggle('ghost',idx===PANELS.length-1);
  // update button text for last panel
  var nb=el('btn_next');
  nb.setAttribute('data-en',idx===PANELS.length-2?'Next ›':'Next ›');
}
el('btn_next').addEventListener('click',function(){goPanel(cur+1);});
el('btn_back').addEventListener('click',function(){goPanel(cur-1);});
qa('.sn').forEach(function(sn){
  sn.addEventListener('click',function(){
    var id=sn.getAttribute('data-to');
    var idx=PANELS.indexOf(id);
