function validHex(v){v=v.replace('#','');if(v.length!==6)return false;for(var i=0;i<6;i++)if('0123456789abcdef'.indexOf(v[i].toLowerCase())<0)return false;return true;}
function setColor(hex){
  el('f_cpick').value=hex;
  el('f_chex').value=hex.toUpperCase();
  qa('.dot').forEach(function(d){d.classList.toggle('on',d.getAttribute('data-c').toLowerCase()===hex.toLowerCase());});
}
el('f_cpick').addEventListener('input',function(){setColor(this.value);});
el('f_chex').addEventListener('input',function(){var v=this.value.trim();if(validHex(v)){if(v[0]!=='#')v='#'+v;el('f_cpick').value=v;}});
