function syncStats(){
  var box=el('stats_box');if(!box)return;
  if(box.children.length>0){
    qa('.stat-lbl',box).forEach(function(lbl,i){
      if(STATS[i])lbl.textContent=L==='th'?STATS[i][2]:STATS[i][1];
    });
    return;
  }
  STATS.forEach(function(s){
    var row=document.createElement('div');row.className='stat-row';
    row.innerHTML='<span class="stat-lbl">'+(L==='th'?s[2]:s[1])+'</span><input class="stat-n" id="st_'+s[0]+'" type="number" min="0" max="1000000" value="10"/>';
    box.appendChild(row);
  });
}

/* ── Skill kit ─────────────────────────────────── */
var KIT={};
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function redrawKit(){
  var box=el('kit_box');if(!box)return;
  var open={};qa('.skill-sec').forEach(function(s,i){open[i]=s.classList.contains('col');});
  var h='';
  SKILLS.forEach(function(cat,ci){
    var label=L==='th'?(cat.ct||cat.cat):cat.cat;
    h+='<div class="skill-sec'+(open[ci]?' col':'')+'"><div class="skill-sec-name"><span class="chev">▾</span>'+esc(label)+'</div><div class="stamp-row">';
    cat.list.forEach(function(sk){
      h+='<span class="stamp'+(KIT[sk.id]?' on':'')+'" data-id="'+esc(sk.id)+'" data-name="'+esc(sk.name)+'" title="'+(L==='th'?(sk.dt||sk.desc):sk.desc)+'">'+esc(sk.name)+'</span>';
    });
    h+='</div></div>';
  });
  box.innerHTML=h;
  qa('.skill-sec-name').forEach(function(h){h.addEventListener('click',function(){h.parentNode.classList.toggle('col');});});
  qa('.stamp').forEach(function(s){
